/** Each Sphinx surveys the types around it — every card in the army but itself. */
const everyCardBut = (army: Card[], excludedIndex: number): Card[] => [
  ...army.slice(0, excludedIndex),
  ...army.slice(excludedIndex + 1),
];

const scoreSphinxAt = (army: Card[], sphinxIndex: number): number =>
  BASE_POINTS + typeBonus(countDistinctTypes(everyCardBut(army, sphinxIndex)));
